define([],function(){let initialized=false;function handleClick(event){if(!(event.target instanceof Element)){return}const button=event.target.closest('[data-action="theme-degrade-password-toggle"]');if(!button){return}const field=button.closest(".theme-degrade-password-field");const input=field?field.querySelector("input"):null;if(!input){return}const visible=input.type==="password";input.type=visible?"text":"password";button.setAttribute("aria-pressed",String(visible));button.setAttribute("aria-label",visible?button.dataset.hideLabel:button.dataset.showLabel);const icon=button.querySelector("i");if(icon){icon.classList.toggle("fa-eye",!visible);icon.classList.toggle("fa-eye-slash",visible)}}return{init:function(){if(initialized){return}document.addEventListener("click",handleClick);initialized=true}}});